type Cache struct{ p atomic.Pointer[map[string]bool] }

func (c *Cache) Get(k string) bool { m := c.p.Load(); return m != nil && (*m)[k] }

func (c *Cache) Set(k string, v bool) {      // build completely ...
    old := c.p.Load()
    next := make(map[string]bool, len(*old)+1)
    for key, val := range *old {
        next[key] = val
    }
    next[k] = v
    c.p.Store(&next)                          // ... then commit with one store
}
